\label{sec:embedding}
We record a minimal embedding convention. The reader may substitute an equivalent
standard convention; our invariance results show the measure is robust to such
choices.

\begin{definition}[Boolean-to-polynomial representation]
\label{def:spdp-boolean}
Let $f:\bits^n\to\bits$. A \emph{polynomial representation} of $f$ is a polynomial
$\tilde f\in\F[x_1,\dots,x_n]$ that agrees with $f$ on $\bits^n$.
Unless otherwise stated, we assume $\tilde f$ is multilinear (via standard
multilinearization modulo $(x_i^2-x_i)$).
\end{definition}

\begin{remark}
\label{rem:non-multilinear}
If a non-multilinear representation is used, all SPDP spaces below may be taken
modulo the Boolean ideal $(x_i^2-x_i)$; this does not affect the rank/codimension
definitions, only the ambient basis choice.
\end{remark}

\label{sec:width-implies-rank}

This section gives the main structural upper bound of the paper:
if a polynomial admits a local (radius-1) description with bounded live-interface width,
then its SPDP rank at logarithmic parameters is polynomially bounded. The width-based
approach draws on ideas from algebraic branching program complexity~\citep{Nisan1991,FS2013,SY2010}.

\label{subsec:poly-width-implies-rank}

\begin{theorem}[Width$\Rightarrow$Rank: polynomial bound]
\label{thm:poly-width-rank}
Assume (A1)--(A4) and (C1)--(C2), together with the deterministic compiler\slash diagonal-basis
structure. Let $p$ be any polynomial computed in a local-width model with width
$R=C(\log n)^c$. Then for $\kappa,\ell=\Theta(\log n)$,
\[
\Gamma_{\kappa,\ell}(p)
\;\le\;
n^{O(1)}.
\]
\end{theorem}

\begin{proof}
Fix $\kappa,\ell=\Theta(\log n)$ and the width parameter $R=C(\log n)^c$.
Let $W$ be the set of canonical windows (under (C1)--(C2)) that contribute
rows to the SPDP matrix $M_{\kappa,\ell}(p)$ in this regime. Each window
$w\in W$ induces a profile histogram $h(w)$ (\ref{def:interface-anonymous-profile}).
Let
\[
H \;:=\; \{\, h(w) : w\in W \,\}
\]
be the set of all realizable interface-anonymous profiles.

\paragraph{Step 1: Bound the number of profiles.}
By \ref{lem:profile-compression-removes-kappa}
(equivalently \ref{cor:poly-many-profiles}),
\[
|H| \;\le\; R^{O(1)}.
\]
Since $R=C(\log n)^c$, it follows that $|H|\le (\log n)^{O(1)}\le n^{O(1)}$.

\paragraph{Step 2: Decompose the SPDP matrix by profile classes.}
Reorder the rows of the global SPDP matrix $M_{\kappa,\ell}(p)$ so that rows coming
from windows with the same profile are grouped together. This yields a vertical
concatenation
\[
M_{\kappa,\ell}(p)
\;=\;
\begin{bmatrix}
M^{(h_1)}\\ \hline
M^{(h_2)}\\ \hline
\vdots\\ \hline
M^{(h_{|H|})}
\end{bmatrix},
\]
where each block $M^{(h)}$ consists exactly of the SPDP rows generated by windows
whose profile is $h$.

For any matrices $A,B$ with the same number of columns,
\[
\rank\!\begin{bmatrix}A\\B\end{bmatrix}
\;\le\;
\rank(A)+\rank(B),
\]
because the row space of $\begin{bmatrix}A\\B\end{bmatrix}$ is contained in
$\mathrm{RowSpan}(A)+\mathrm{RowSpan}(B)$ and therefore has dimension at most the
sum of dimensions. Iterating this inequality over the block decomposition gives
\begin{equation}
\label{eq:rank-sum-over-profiles}
\Gamma_{\kappa,\ell}(p)
\;=\;
\rank(M_{\kappa,\ell}(p))
\;\le\;
\sum_{h\in H} \rank(M^{(h)}).
\end{equation}

\paragraph{Step 3: Bound the rank contribution of a fixed profile via subspace dimension.}
Fix $h\in H$. Let $V_h$ be the subspace of the ambient coefficient space spanned by
all SPDP rows generated by windows with profile $h$. Then $\rank(M^{(h)})=\dim V_h$.

By \ref{lem:profile-subspace-dim}, under the deterministic compiler\slash diagonal-basis
assumption, each profile subspace has dimension
\[
\dim V_h \;\le\; (\log n)^{O(1)}.
\]

\paragraph{Step 4: Combine the bounds.}
Combining \eqref{eq:rank-sum-over-profiles} with the profile count and subspace
dimension bounds yields
\[
\Gamma_{\kappa,\ell}(p)
\;\le\;
\sum_{h\in H} \dim V_h
\;\le\;
|H|\cdot (\log n)^{O(1)}
\;\le\;
R^{O(1)}\cdot (\log n)^{O(1)}.
\]
Since $R = C(\log n)^c$, this gives
\[
\Gamma_{\kappa,\ell}(p)
\;\le\;
(\log n)^{O(1)} \cdot (\log n)^{O(1)}
\;=\;
(\log n)^{O(1)}
\;=\;
n^{O(1)},
\]
as claimed.
\end{proof}

\begin{remark}
The key ingredients are:
\begin{enumerate}
\item[(i)] \ref{lem:profile-compression-removes-kappa} and \ref{cor:poly-many-profiles},
which show that the number of interface-anonymous profiles is $R^{O(1)}$, independent of $\kappa$,
by exploiting the normal-form compression of canonical windows;
\item[(ii)] \ref{lem:profile-subspace-dim}, which shows each profile subspace has
polylogarithmic dimension $(\log n)^{O(1)}$ under the compiler\slash diagonal-basis structure;
\item[(iii)] \ref{lem:block-perm-invariance}, which ensures within-profile permutations
do not inflate rank.
\end{enumerate}
The combination yields the $n^{O(1)}$ bound, which is strictly stronger than the
naive $n^{O(\log n)}$ bound one would obtain from crude monomial counting alone.
\end{remark}

\begin{corollary}[Fixed $\ell$: polynomial rank]
\label{cor:poly-rank-fixed-ell}
Assume (A1)--(A3), (C1)--(C2), and the deterministic compiler\slash diagonal-basis structure.
Let $\kappa=\Theta(\log n)$, $R=C(\log n)^c$, and $\ell=O(1)$ be fixed (e.g.\ $\ell\in\{2,3\}$).
Then
\[
\Gamma_{\kappa,\ell}(p) \;\le\; n^{O(1)}.
\]
\end{corollary}

\begin{proof}
By \ref{cor:poly-many-profiles}, the number of interface-anonymous profiles
satisfies $|H|\le R^{O(1)}$, independent of $\kappa$. By \ref{lem:profile-subspace-dim},
each profile subspace has $\dim V_h \le (\log n)^{O(1)}$. Hence
\[
\Gamma_{\kappa,\ell}(p)
\;\le\;
|H|\cdot \dim V_h
\;\le\;
R^{O(1)}\cdot (\log n)^{O(1)}.
\]
Since $R = C(\log n)^c$, this gives
\[
\Gamma_{\kappa,\ell}(p) \;\le\; (\log n)^{O(1)} \;=\; n^{O(1)}.
\]
Note that fixing $\ell=O(1)$ does not improve the profile count $|H|$, which is the
dominant factor; the improvement from fixed $\ell$ only affects the monomial-choice
contribution, which is already subsumed by the profile subspace dimension bound.
\end{proof}

\begin{remark}
\ref{cor:poly-rank-fixed-ell} is the regime used in separation arguments:
fixing $\ell \in \{2,3\}$ while taking $\kappa = \Theta(\log n)$ yields polynomial
SPDP rank for width-bounded computations. This is strictly
stronger than the naive $n^{O(\log n)}$ bound one would obtain without the profile
compression (\ref{lem:profile-compression-removes-kappa}), and can be compared
against exponential lower bounds for explicit hard polynomials such as the permanent.
\end{remark}

\label{sec:sanity-checks}

The results in this section are not part of the main theoretical development;
they provide empirical evidence supporting the expected superpolynomial
separation between P-side and NP-side SPDP rank behavior.

Reference implementations and empirical validation code are available at
\url{https://github.com/darrenjedwards/spdp}.

